## Why This Is Asked
This question tests the fundamental understanding of combining data structures to achieve O(1) operations while maintaining an ordering constraint. It evaluates knowledge of hash map + linked list patterns and eviction logic commonly used in caching systems.

## Key Concepts
- HashMap for O(1) key-to-node lookups
- Doubly linked list for maintaining recency order
- Node manipulation for constant-time recency updates
- Edge case handling: missing keys, capacity limits, and duplicate operations

## Code Example
```javascript
class LRUCache {
  constructor(capacity) {
    this.capacity = capacity;
    this.cache = new Map();
    this.head = { prev: null, next: null };
    this.tail = { prev: null, next: null };
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }

  get(key) {
    if (!this.cache.has(key)) return -1;
    const node = this.cache.get(key);
    this._moveToHead(node);
    return node.value;
  }

  put(key, value) {
    if (this.cache.has(key)) {
      const node = this.cache.get(key);
      node.value = value;
      this._moveToHead(node);
    } else {
      const newNode = { key, value, prev: null, next: null };
      this.cache.set(key, newNode);
      this._addToHead(newNode);
      if (this.cache.size > this.capacity) {
        this._removeTail();
      }
    }
  }

  _moveToHead(node) {
    this._removeNode(node);
    this._addToHead(node);
  }

  _addToHead(node) {
    node.prev = this.head;
    node.next = this.head.next;
    this.head.next.prev = node;
    this.head.next = node;
  }

  _removeNode(node) {
    node.prev.next = node.next;
    node.next.prev = node.prev;
  }

  _removeTail() {
    const node = this.tail.prev;
    this._removeNode(node);
    this.cache.delete(node.key);
  }
}
```

## Why This Is Asked
Tests ability to design a compact, efficient dynamic interval structure using classic DS tools (Fenwick, coordinate compression) and to reason about duplicates and point/range queries.

## Key Concepts
- Range update, point query via Fenwick trees
- Two-BIT technique for range add + range sum
- Coordinate compression for discrete integer endpoints
- Handling duplicates by counting multiplicities

## Code Example
```javascript
class Fenwick { constructor(n){ this.n=n; this.f=new Array(n+2).fill(0); } add(i,d){ for(;i<=this.n;i+=i&-i) this.f[i]+=d; } sum(i){ let s=0; for(;i>0;i-=i&-i) s+=this.f[i]; return s; } }
class IntervalDS {
  constructor(coords){
    this.coords = Array.from(new Set(coords)).sort((a,b)=>a-b);
    this.idx = new Map(this.coords.map((v,i)=>[v,i+1]));
    this.n = this.coords.length+2;
    this.B1 = new Fenwick(this.n);
    this.B2 = new Fenwick(this.n);
  }
  _upd(l,r,sign){ const L=this.idx.get(l); const R=this.idx.get(r+1); this.B1.add(L,sign); this.B1.add(R,-sign); this.B2.add(L,sign*(l-1)); this.B2.add(R,-sign*r); }
  insert(l,r){ this._upd(l,r,1); }
  erase(l,r){ this._upd(l,r,-1); }
  _pref(p){ // largest coord <= p
    let i = 0; // placeholder for upper_bound on this.coords
    // implement as needed in real code
    return this.B1.sum(i)*p - this.B2.sum(i);
  }
  countCover(x){ return this._pref(x) - this._pref(x-1); }
  coverageInRange(a,b){ return this._pref(b) - this._pref(a-1); }
}
```

